/**
 * The E3 dataset (data/suppliers/eval, generated by data/suppliers/build.mjs) read through the real set loader, and
 * its labels (labels.jsonl) checked against the listings they describe. This tests the DATASET's integrity only; how
 * many planted defects the shipped gates catch is E3's measurement, not asserted here.
 */
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { SUPPLIER_DEFECTS, SupplierEvalLabel, relevantCertificates, type SupplierDefect } from "@hogee/core";
import type { SupplierEvalSet } from "../src/context";
import { fileCatalog } from "../src/runtime/catalog";
import { DATA_DIR, collectingLog, onUnList, usccChecksumOk } from "./support/supplier-data";

const SET_IDS = Array.from({ length: 20 }, (_, i) => `set-${String(i + 1).padStart(2, "0")}`);
const LABELS = readFileSync(join(DATA_DIR, "suppliers", "eval", "labels.jsonl"), "utf8")
  .split("\n")
  .filter((l) => l.length > 0)
  .map((l) => SupplierEvalLabel.parse(JSON.parse(l)));

async function loadSets(): Promise<SupplierEvalSet[]> {
  const log = collectingLog();
  const cat = fileCatalog(DATA_DIR, log);
  const sets = await Promise.all(SET_IDS.map((id) => cat.supplierEvalSet(id)));
  expect(log.events).toEqual([]);
  return sets.map((s, i) => {
    if (!s) throw new Error(`${SET_IDS[i]} did not load`);
    return s;
  });
}

/** The code-point slice [start, end) of `text` (the label span convention). */
const slice = (text: string, span: { start: number; end: number }) => Array.from(text).slice(span.start, span.end).join("");

describe("data/suppliers/eval (E3) through the real set loader", () => {
  it("20 sets x 5 listings, each with its spec and readable listing text", async () => {
    const sets = await loadSets();
    for (const s of sets) {
      expect(s.listings).toHaveLength(5);
      expect(s.spec).toEqual({ productCategory: "drinkware_food_contact", buyFrom: "CN", quantity: 1000, budgetMinor: "1000000" });
      expect(s.listings.every((l) => l.listingText !== null && l.supplier.country === "CN" && l.supplier.listing.sourceType === "mock")).toBe(true);
      expect(s.listings.every((l) => l.supplier.ids.uscc === undefined || usccChecksumOk(l.supplier.ids.uscc))).toBe(true);
    }
  });

  it("one label per listing; every defect type planted at least 3 times; humanRank empty until labelled", async () => {
    const sets = await loadSets();
    const listed = sets.flatMap((s) => s.listings.map((l) => `${s.setId}/${l.supplier.supplierId}`)).sort();
    expect(LABELS.map((l) => `${l.setId}/${l.supplierId}`).sort()).toEqual(listed);
    const count = (t: SupplierDefect) => LABELS.filter((l) => l.defects.some((d) => d.type === t)).length;
    for (const t of SUPPLIER_DEFECTS) expect(count(t), t).toBeGreaterThanOrEqual(3);
    expect(LABELS.every((l) => l.humanRank.length === 0)).toBe(true);
    // Every set keeps at least two listings that should be ranked.
    for (const id of SET_IDS) expect(LABELS.filter((l) => l.setId === id && !l.expectedExcluded).length).toBeGreaterThanOrEqual(2);
  });

  it("each label matches its listing: spans point at the planted sentence, structured defects are in the record", async () => {
    const sets = await loadSets();
    const spec = sets[0]?.spec;
    if (!spec) throw new Error("no spec");
    for (const label of LABELS) {
      const f = sets.find((s) => s.setId === label.setId)?.listings.find((l) => l.supplier.supplierId === label.supplierId);
      if (!f || f.listingText === null) throw new Error(`${label.setId}/${label.supplierId} missing`);
      const s = f.supplier;
      const text = f.listingText;
      const types = new Set(label.defects.map((d) => d.type));
      for (const d of label.defects) {
        if (!d.span) continue;
        const planted = slice(text, d.span);
        expect(planted.length, `${label.supplierId} ${d.type}`).toBeGreaterThan(0);
        expect(text.split("\n"), `${label.supplierId} ${d.type} span is a whole sentence`).toContain(planted);
      }
      const food = relevantCertificates(s, spec.productCategory);
      const key = `${label.setId}/${label.supplierId}`;
      expect(s.terms.escrow, key).toBe(!types.has("NO_ESCROW"));
      expect(s.terms.payeeType, key).toBe(types.has("PERSONAL_PAYEE") ? "personal" : "company");
      expect(food.length === 0, key).toBe(types.has("MISSING_CERT"));
      expect(s.offer.moq > spec.quantity, key).toBe(types.has("OVER_MOQ"));
      expect(onUnList(s.displayName), key).toBe(types.has("SANCTIONS"));
      expect(food.length > 0 && food.every((c) => c.tier === "tier3"), key).toBe(types.has("FAKE_REPORT"));
      const offPlatform = s.terms.offPlatformDiscount || label.defects.some((d) => d.type === "OFF_PLATFORM_DISCOUNT" && d.span);
      expect(offPlatform, key).toBe(types.has("OFF_PLATFORM_DISCOUNT"));
      if (types.has("AI_INJECTION")) expect(label.defects.find((d) => d.type === "AI_INJECTION")?.span, key).toBeDefined();
      if (types.has("SANCTIONS")) expect(s.xenditTest.holderName, key).toBe("SANCTIONS SCREENING TEST ROW - DO NOT PAY");
    }
  });
});
